const items = $input.all();

const requiredFields = [
  'requester_email',
  'service_name',
  'service_category',
  'use_case',
  'data_types',
  'access_level',
  'model_training',
  'sso_available',
  'audit_logs',
  'deletion_supported',
  'business_criticality',
  'request_id',
  'received_at',
];

const allowedValues = {
  service_category: [
    'saas',
    'generative_ai',
    'both',
  ],
  access_level: [
    'none',
    'read',
    'write',
    'admin',
  ],
  model_training: [
    'not_applicable',
    'no',
    'optout',
    'yes',
    'unknown',
  ],
  sso_available: [
    'yes',
    'no',
    'unknown',
  ],
  audit_logs: [
    'yes',
    'no',
    'unknown',
  ],
  deletion_supported: [
    'yes',
    'no',
    'unknown',
  ],
  business_criticality: [
    'low',
    'medium',
    'high',
  ],
};

const allowedDataTypes = [
  'public',
  'internal',
  'confidential',
  'personal',
  'credentials',
  'payment',
];

const maxLengths = {
  requester_email: 320,
  service_name: 200,
  use_case: 4000,
  data_region: 200,
  evidence_notes: 4000,
};

const secretPatterns = [
  {
    name: 'private_key',
    regex:
      /-----BEGIN(?: [A-Z0-9]+)* PRIVATE KEY-----[\s\S]*?-----END(?: [A-Z0-9]+)* PRIVATE KEY-----/g,
  },
  {
    name: 'aws_access_key',
    regex: /\b(?:AKIA|ASIA)[0-9A-Z]{16}\b/g,
  },
  {
    name: 'github_token',
    regex:
      /\b(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{20,255}\b|\bgithub_pat_[A-Za-z0-9_]{20,255}\b/g,
  },
  {
    name: 'slack_token',
    regex: /\bxox[baprs]-[A-Za-z0-9-]{10,}\b/g,
  },
  {
    name: 'bearer_token',
    regex: /\bBearer\s+[A-Za-z0-9\-._~+/]+=*/gi,
  },
  {
    name: 'generic_secret',
    regex:
      /\b(?:api[_-]?key|secret|token|password|passwd)\s*[:=]\s*["']?[A-Za-z0-9_\-./+=]{8,}["']?/gi,
  },
];

const promptInjectionPatterns = [
  {
    name: 'IGNORE_PREVIOUS_INSTRUCTIONS_EN',
    regex:
      /ignore\s+(all\s+)?(previous|prior)\s+(instructions|messages)/i,
  },
  {
    name: 'REVEAL_SYSTEM_PROMPT_EN',
    regex:
      /reveal\s+(the\s+)?(system|developer)\s+(prompt|message)/i,
  },
  {
    name: 'SYSTEM_PROMPT_REFERENCE_EN',
    regex: /\bsystem\s+prompt\b/i,
  },
  {
    name: 'IGNORE_PREVIOUS_INSTRUCTIONS_JA',
    regex:
      /(以前|前)の(指示|命令).*(無視|破棄)/i,
  },
  {
    name: 'SYSTEM_PROMPT_REFERENCE_JA',
    regex: /システムプロンプト/i,
  },
  {
    name: 'FORCE_LOW_RISK',
    regex:
      /((low|低リスク).*(承認|判定))|((承認|判定).*(low|低リスク))/i,
  },
];

function isBlank(value) {
  if (value === undefined || value === null) {
    return true;
  }

  if (typeof value === 'string') {
    return value.trim() === '';
  }

  if (Array.isArray(value)) {
    return value.length === 0;
  }

  return false;
}

function trimString(value) {
  return typeof value === 'string'
    ? value.trim()
    : value;
}

function scrub(value, path, hits) {
  if (typeof value === 'string') {
    let result = value;

    for (const pattern of secretPatterns) {
      const regex = new RegExp(
        pattern.regex.source,
        pattern.regex.flags
      );

      result = result.replace(regex, () => {
        hits.push({
          type: pattern.name,
          path,
        });

        return `[REDACTED:${pattern.name}]`;
      });
    }

    return result;
  }

  if (Array.isArray(value)) {
    return value.map((entry, index) =>
      scrub(entry, `${path}[${index}]`, hits)
    );
  }

  if (
    value !== null &&
    typeof value === 'object'
  ) {
    return Object.fromEntries(
      Object.entries(value).map(([key, entry]) => [
        key,
        scrub(entry, `${path}.${key}`, hits),
      ])
    );
  }

  return value;
}

return items.map((item, index) => {
  const source = item.json;

  const normalized = {
    ...source,
    requester_email:
      trimString(source.requester_email),
    service_name:
      trimString(source.service_name),
    service_category:
      trimString(source.service_category),
    use_case:
      trimString(source.use_case),
    access_level:
      trimString(source.access_level),
    model_training:
      trimString(source.model_training),
    sso_available:
      trimString(source.sso_available),
    audit_logs:
      trimString(source.audit_logs),
    data_region:
      trimString(source.data_region),
    deletion_supported:
      trimString(source.deletion_supported),
    business_criticality:
      trimString(source.business_criticality),
    evidence_notes:
      trimString(source.evidence_notes),
  };

  const errors = [];
  const missingFields = [];
  const tooLongFields = [];
  const invalidFields = [];

  // 1. Required-field validation
  for (const field of requiredFields) {
    if (isBlank(normalized[field])) {
      missingFields.push(field);

      errors.push({
        code: 'REQUIRED_FIELD_MISSING',
        field,
      });
    }
  }

  // 2. Email format validation
  if (
    !isBlank(normalized.requester_email) &&
    !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(
      normalized.requester_email
    )
  ) {
    invalidFields.push('requester_email');

    errors.push({
      code: 'INVALID_EMAIL_FORMAT',
      field: 'requester_email',
    });
  }

  // 3. String-length validation
  for (
    const [field, maximum]
    of Object.entries(maxLengths)
  ) {
    const value = normalized[field];

    if (
      typeof value === 'string' &&
      value.length > maximum
    ) {
      tooLongFields.push(field);

      errors.push({
        code: 'MAX_LENGTH_EXCEEDED',
        field,
        maximum,
        actual: value.length,
      });
    }
  }

  // 4. Enum validation
  for (
    const [field, allowed]
    of Object.entries(allowedValues)
  ) {
    const value = normalized[field];

    if (
      !isBlank(value) &&
      !allowed.includes(value)
    ) {
      invalidFields.push(field);

      errors.push({
        code: 'INVALID_ALLOWED_VALUE',
        field,
        value,
      });
    }
  }

  // 5. Data Types validation
  if (!Array.isArray(normalized.data_types)) {
    invalidFields.push('data_types');

    errors.push({
      code: 'DATA_TYPES_MUST_BE_ARRAY',
      field: 'data_types',
    });
  } else {
    const invalidDataTypes =
      normalized.data_types.filter(
        (value) =>
          !allowedDataTypes.includes(value)
      );

    if (invalidDataTypes.length > 0) {
      invalidFields.push('data_types');

      errors.push({
        code: 'INVALID_DATA_TYPE',
        field: 'data_types',
        values: invalidDataTypes,
      });
    }
  }

  // 6. Detect and redact likely secrets.
  const secretHits = [];

  const redacted = scrub(
    normalized,
    'request',
    secretHits
  );

  // 7. Prompt-injection heuristic.
  const textToInspect = [
    redacted.service_name,
    redacted.use_case,
    redacted.evidence_notes,
  ]
    .filter(
      (value) =>
        typeof value === 'string'
    )
    .join('\n');

  const anomalyFlags = [];

  for (
    const pattern of promptInjectionPatterns
  ) {
    if (pattern.regex.test(textToInspect)) {
      anomalyFlags.push({
        type: 'PROMPT_INJECTION_SUSPECTED',
        rule: pattern.name,
      });
    }
  }

  // 8. Create minimal payload that may be
  //    sent to the LLM on a later day.
  //    Requester email is intentionally excluded.
  const llmPayload = {
    service_name:
      redacted.service_name,
    service_category:
      redacted.service_category,
    use_case:
      redacted.use_case,
    data_types:
      redacted.data_types,
    access_level:
      redacted.access_level,
    model_training:
      redacted.model_training,
    sso_available:
      redacted.sso_available,
    audit_logs:
      redacted.audit_logs,
    data_region:
      redacted.data_region || null,
    deletion_supported:
      redacted.deletion_supported,
    business_criticality:
      redacted.business_criticality,
    evidence_notes:
      redacted.evidence_notes || null,
  };

  const validationValid =
    errors.length === 0;

  let intakeRoute;

  if (!validationValid) {
    intakeRoute = 'needs_info';
  } else if (
    secretHits.length > 0 ||
    anomalyFlags.length > 0
  ) {
    intakeRoute = 'manual_review';
  } else {
    intakeRoute = 'ready_for_ai';
  }

  return {
    json: {
      ...redacted,

      validation: {
        valid: validationValid,
        errors,
        missing_fields: [
          ...new Set(missingFields),
        ],
        too_long_fields: [
          ...new Set(tooLongFields),
        ],
        invalid_fields: [
          ...new Set(invalidFields),
        ],
      },

      secret_hits: secretHits,
      anomaly_flags: anomalyFlags,

      llm_payload: llmPayload,

      intake_route: intakeRoute,
    },

    pairedItem: {
      item: index,
    },
  };
});

const items = $input.all();

const dataTypeWeights = {
  public: 0,
  internal: 8,
  confidential: 20,
  personal: 20,
  credentials: 35,
  payment: 35,
};

const fieldWeights = {
  access_level: {
    none: 0,
    read: 5,
    write: 15,
    admin: 25,
  },
  model_training: {
    not_applicable: 0,
    no: 0,
    optout: 5,
    unknown: 10,
    yes: 25,
  },
  sso_available: {
    yes: 0,
    unknown: 4,
    no: 8,
  },
  audit_logs: {
    yes: 0,
    unknown: 8,
    no: 15,
  },
  deletion_supported: {
    yes: 0,
    unknown: 8,
    no: 15,
  },
  business_criticality: {
    low: 0,
    medium: 8,
    high: 15,
  },
};

function addReason(
  reasons,
  code,
  points,
  evidence,
) {
  if (points <= 0) {
    return;
  }

  reasons.push({
    code,
    points,
    evidence,
  });
}

function unique(values) {
  return [...new Set(values)];
}

return items.map((item, index) => {
  const source = item.json;

  const dataTypes =
    Array.isArray(source.data_types)
      ? source.data_types
      : [];

  let score = 0;
  const scoreReasons = [];
  const hardReviewFlags = [];

  /*
   * Data Typesは合算せず、
   * 選択された中で最大の感度点だけを使います。
   *
   * 例:
   * confidential + personal
   * → 20 + 20ではなく20
   */
  const dataSensitivityScore = Math.max(
    0,
    ...dataTypes.map(
      (value) =>
        dataTypeWeights[value] ?? 0,
    ),
  );

  score += dataSensitivityScore;

  addReason(
    scoreReasons,
    'DATA_SENSITIVITY',
    dataSensitivityScore,
    `data_types=${dataTypes.join(',') || 'none'}`,
  );

  for (
    const [field, weights]
    of Object.entries(fieldWeights)
  ) {
    const value = source[field];
    const points = weights[value] ?? 0;

    score += points;

    addReason(
      scoreReasons,
      field.toUpperCase(),
      points,
      `${field}=${value ?? 'undefined'}`,
    );
  }

  const dataRegion =
    typeof source.data_region === 'string'
      ? source.data_region.trim()
      : '';

  const dataRegionUnknown =
    dataRegion === '' ||
    /^unknown$/i.test(dataRegion);

  if (dataRegionUnknown) {
    score += 5;

    addReason(
      scoreReasons,
      'DATA_REGION_UNKNOWN',
      5,
      `data_region=${dataRegion || 'blank'}`,
    );
  }

  const sensitiveData = dataTypes.some(
    (value) =>
      [
        'confidential',
        'personal',
        'credentials',
        'payment',
      ].includes(value),
  );

  const restrictedData = dataTypes.some(
    (value) =>
      [
        'credentials',
        'payment',
      ].includes(value),
  );

  /*
   * 点数とは別の強制レビュー条件です。
   */
  if (restrictedData) {
    hardReviewFlags.push(
      'RESTRICTED_DATA_TYPE',
    );
  }

  if (
    source.access_level === 'admin' &&
    sensitiveData
  ) {
    hardReviewFlags.push(
      'ADMIN_WITH_SENSITIVE_DATA',
    );
  }

  if (
    source.model_training === 'yes' &&
    sensitiveData
  ) {
    hardReviewFlags.push(
      'TRAINING_WITH_SENSITIVE_DATA',
    );
  }

  if (
    source.audit_logs === 'no' &&
    source.business_criticality === 'high'
  ) {
    hardReviewFlags.push(
      'HIGH_CRITICALITY_WITHOUT_AUDIT_LOGS',
    );
  }

  const rawScore = score;
  score = Math.min(rawScore, 100);

  let riskLevel = 'low';

  if (score >= 70) {
    riskLevel = 'high';
  } else if (score >= 25) {
    riskLevel = 'medium';
  }

  /*
   * Hard flagが1つでもあれば、
   * スコアにかかわらずHighへ引き上げます。
   */
  if (hardReviewFlags.length > 0) {
    riskLevel = 'high';
  }

  /*
   * このPoCではMedium以上を
   * 人手レビュー対象とします。
   */
  const requiresHumanReview =
    riskLevel !== 'low' ||
    hardReviewFlags.length > 0;

  return {
    json: {
      ...source,

      rule_assessment: {
        version:
          source.rule_version || '1.0.0',

        raw_score: rawScore,
        score,
        risk_level: riskLevel,

        requires_human_review:
          requiresHumanReview,

        score_reasons: scoreReasons,

        hard_review_flags:
          unique(hardReviewFlags),
      },
    },

    pairedItem: {
      item: index,
    },
  };
});

const items = $input.all();

const ruleItems =
  $('Calculate Deterministic Risk').all();

const riskRank = {
  low: 0,
  medium: 1,
  high: 2,
};

function unique(values) {
  return [...new Set(values)];
}

return items.map((item, index) => {
  const current = item.json;

  const requestId = current.request_id;

  const ruleSource = ruleItems.find(
    (ruleItem) =>
      ruleItem.json.request_id === requestId
  );

  if (!ruleSource) {
    throw new Error(
      `Rule assessment not found for request_id=${requestId}`
    );
  }

  const ruleAssessment =
    ruleSource.json.rule_assessment;

  const aiAssessment =
    current.output;

  if (
    !aiAssessment ||
    typeof aiAssessment !== 'object'
  ) {
    throw new Error(
      'AI assessment output is missing.'
    );
  }

  if (!ruleAssessment) {
    throw new Error(
      'Rule assessment output is missing.'
    );
  }

  const ruleRiskLevel =
    ruleAssessment.risk_level;

  const aiRiskLevel =
    aiAssessment.recommended_risk_level;

  if (
    !(ruleRiskLevel in riskRank) ||
    !(aiRiskLevel in riskRank)
  ) {
    throw new Error(
      'Unsupported risk level detected.'
    );
  }

  const levelGap = Math.abs(
    riskRank[ruleRiskLevel] -
    riskRank[aiRiskLevel]
  );

  // AIがルール基準を引き下げないよう、
  // 高い方をトリアージレベルにする。
  const triageRiskLevel =
    riskRank[ruleRiskLevel] >=
    riskRank[aiRiskLevel]
      ? ruleRiskLevel
      : aiRiskLevel;

  const humanReviewDisagreement =
    Boolean(
      ruleAssessment.requires_human_review
    ) !==
    Boolean(
      aiAssessment.requires_human_review
    );

  const reviewReasons = [];

  if (
    ruleAssessment.requires_human_review
  ) {
    reviewReasons.push(
      'RULE_ENGINE_REQUIRES_REVIEW'
    );
  }

  if (
    aiAssessment.requires_human_review
  ) {
    reviewReasons.push(
      'AI_RECOMMENDS_REVIEW'
    );
  }

  if (levelGap > 0) {
    reviewReasons.push(
      'RISK_LEVEL_DISAGREEMENT'
    );
  }

  if (humanReviewDisagreement) {
    reviewReasons.push(
      'HUMAN_REVIEW_DISAGREEMENT'
    );
  }

  if (triageRiskLevel === 'high') {
    reviewReasons.push(
      'HIGH_TRIAGE_RISK'
    );
  }

  const reviewRequired =
    reviewReasons.length > 0;

  return {
    json: {
      ...current,

      rule_assessment:
        ruleAssessment,

      assessment_comparison: {
        version: '1.0.0',

        rule_risk_level:
          ruleRiskLevel,

        ai_recommended_risk_level:
          aiRiskLevel,

        triage_risk_level:
          triageRiskLevel,

        level_gap:
          levelGap,

        level_disagreement:
          levelGap > 0,

        human_review_disagreement:
          humanReviewDisagreement,

        policy_floor_applied:
          riskRank[ruleRiskLevel] >
          riskRank[aiRiskLevel],

        review_required:
          reviewRequired,

        review_reasons:
          unique(reviewReasons),

        automatic_approval:
          false,
      },
    },

    pairedItem: {
      item: index,
    },
  };
});

const items = $input.all();

const sourceItems =
  $('Calculate Deterministic Risk').all();

const executionId =
  String($execution.id);

function requireValue(
  object,
  key,
  label = key,
) {
  const value = object?.[key];

  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    throw new Error(
      `Required persistence field is missing: ${label}`,
    );
  }

  return value;
}

return items.map((item, index) => {
  const finalResult = item.json;

  const requestId =
    requireValue(
      finalResult,
      'request_id',
    );

  const source =
    sourceItems.find(
      (sourceItem) =>
        sourceItem.json.request_id ===
        requestId,
    )?.json;

  if (!source) {
    throw new Error(
      `Original request not found for request_id=${requestId}`,
    );
  }

  const ruleAssessment =
    requireValue(
      finalResult,
      'rule_assessment',
    );

  const aiAssessment =
    requireValue(
      finalResult,
      'output',
    );

  const comparison =
    requireValue(
      finalResult,
      'assessment_comparison',
    );

  const eventType =
    finalResult.status ===
    'PENDING_HUMAN_RISK_REVIEW'
      ? 'HUMAN_RISK_REVIEW_QUEUED'
      : 'RISK_ASSESSMENT_COMPLETED';

  const eventAt =
    new Date().toISOString();

  const ruleVersion =
    source.rule_version ||
    ruleAssessment.version ||
    '1.0.0';

  const comparisonVersion =
    comparison.version ||
    '1.0.0';

  const record = {
    request_id: requestId,

    received_at:
      requireValue(
        source,
        'received_at',
      ),

    submitted_at:
      source.submittedAt || null,

    requester_email:
      requireValue(
        source,
        'requester_email',
      ),

    service_name:
      requireValue(
        source,
        'service_name',
      ),

    service_category:
      requireValue(
        source,
        'service_category',
      ),

    status:
      requireValue(
        finalResult,
        'status',
      ),

    review_queue:
      requireValue(
        finalResult,
        'review_queue',
      ),

    rule_score:
      requireValue(
        ruleAssessment,
        'score',
      ),

    rule_risk_level:
      requireValue(
        ruleAssessment,
        'risk_level',
      ),

    ai_recommended_risk_level:
      requireValue(
        aiAssessment,
        'recommended_risk_level',
      ),

    triage_risk_level:
      requireValue(
        comparison,
        'triage_risk_level',
      ),

    requires_human_review:
      Boolean(
        comparison.review_required,
      ),

    rule_version:
      ruleVersion,

    prompt_version:
      source.prompt_version ||
      finalResult.ai_prompt_version ||
      '1.0.0',

    ai_model:
      requireValue(
        finalResult,
        'ai_model',
      ),

    ai_assessed_at:
      requireValue(
        finalResult,
        'ai_assessed_at',
      ),

    source:
      source.source ||
      'n8n_form',

    workflow_execution_id:
      executionId,

    request_payload:
      requireValue(
        source,
        'llm_payload',
      ),

    rule_assessment:
      ruleAssessment,

    ai_assessment:
      aiAssessment,

    assessment_comparison:
      comparison,

    event_key: [
      requestId,
      eventType,
      `rule-${ruleVersion}`,
      `reconcile-${comparisonVersion}`,
      finalResult.status,
    ].join(':'),

    event_type:
      eventType,

    event_at:
      eventAt,

    actor_type:
      'workflow',

    actor_id:
      'n8n',

    event_details: {
      final_status:
        finalResult.status,

      review_queue:
        finalResult.review_queue,

      rule_score:
        ruleAssessment.score,

      rule_risk_level:
        ruleAssessment.risk_level,

      ai_recommended_risk_level:
        aiAssessment
          .recommended_risk_level,

      ai_confidence:
        aiAssessment.confidence,

      triage_risk_level:
        comparison.triage_risk_level,

      review_required:
        comparison.review_required,

      review_reasons:
        comparison.review_reasons || [],

      hard_review_flags:
        ruleAssessment
          .hard_review_flags || [],
    },
  };

  const serialized =
    JSON.stringify(record);

  return {
    json: {
      ...finalResult,

      persistence_record:
        record,

      persistence_record_b64:
        Buffer
          .from(
            serialized,
            'utf8',
          )
          .toString(
            'base64',
          ),
    },

    pairedItem: {
      item: index,
    },
  };
});
